import json, re
from collections import defaultdict

with open('/home/ubuntu/.claude-account-5/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-8-projects-acr-vla-conformal-refinement/8c290cbe-aa35-4006-bed3-2d946febaa53/tool-results/mcp-agent-ml-research-read_registry-1779983442741.txt', 'r') as f:
    raw = json.load(f)
inner = json.loads(raw['result'])
exps = inner['data']['experiments']

# Helper to normalize SR to 0-1 scale
def norm_sr(val):
    if val is None or val == 'N/A':
        return None
    if isinstance(val, str):
        val = val.replace('%', '').strip()
        try:
            val = float(val.split('/')[0])  # handle "11.0% (11/100)" format
        except:
            return None
    if val > 1:
        val = val / 100.0
    return round(val, 4)

def get_sr(m):
    """Get SR from metrics dict, trying all known keys"""
    for key in ['success_rate', 'overall_success_rate', 'SR', 'overall_sr', 'sr']:
        if key in m:
            return norm_sr(m[key])
    return None

# ==========================================
# Build a comprehensive table of the MAIN experimental conditions
# Focus on experiments with metrics and successful conclusions
# ==========================================

# We want to aggregate by: (method, benchmark, seed) -> SR
# Methods: vla-only, crm-obs-only (norm005), reconvla, k2mean, adaptive-tau025, obs-only
# Benchmarks: spatial, object, goal, long

results = defaultdict(dict)  # (method, benchmark) -> {seed: SR}

for eid, ed in exps.items():
    m = ed.get('metrics', {})
    if not isinstance(m, dict): m = {}
    sr = get_sr(m)

    # Skip entries without SR
    if sr is None:
        continue

    # Skip very low SR (likely broken runs, e.g. SR < 0.2 for main methods)
    # But keep for random-selection and adaptive-k which are legitimately low

    # Determine benchmark
    bench = None
    if 'spatial' in eid: bench = 'spatial'
    elif 'object' in eid or '-obj' in eid: bench = 'object'
    elif 'goal' in eid: bench = 'goal'
    elif 'long' in eid: bench = 'long'
    if not bench:
        bench_from_m = m.get('benchmark')
        if bench_from_m: bench = bench_from_m

    if not bench:
        continue

    # Determine seed
    seed_match = re.search(r'seed(\d+)|[-_]s(\d+)', eid)
    seed = seed_match.group(1) or seed_match.group(2) if seed_match else m.get('seed')
    if seed: seed = int(seed)

    # Determine method
    method = None

    # SUPPLEMENTARY experiments (the most complete set)
    if 'supp' in eid:
        if 'adapt-tau025' in eid or 'adapt_tau025' in eid:
            method = 'adaptive-conformal-crm-tau025'
        elif 'crm-norm005' in eid or 'crm005' in eid:
            method = 'crm-obs-only-norm005'
        elif 'k2mean' in eid:
            method = 'k2mean-baseline'
        elif 'reconvla' in eid:
            method = 'reconvla'
        elif 'vla-only' in eid:
            method = 'vla-only'
        elif 'adapt' in eid and 'tau025' in eid:
            method = 'adaptive-conformal-crm-tau025'
        elif 'obj-crm-norm005' in eid:
            method = 'crm-obs-only-norm005'
        elif 'obj-adapt' in eid:
            method = 'adaptive-conformal-crm-tau025'
        elif 'crm' in eid and 'norm' in eid:
            # various norm experiments
            continue
        else:
            continue

    # VLA-only baseline
    elif ('vla-only' in eid or 'vla_only' in eid) and 'supp' not in eid:
        if sr < 0.3:  # skip broken runs
            continue
        method = 'vla-only'

    # CRM obs-only
    elif 'crm' in eid and ('norm005' in eid or 'norm0.05' in eid or 'crm005' in eid) and 'supp' not in eid:
        if sr < 0.3:
            continue
        method = 'crm-obs-only-norm005'

    # Adaptive tau025
    elif 'adapt' in eid and 'tau025' in eid and 'supp' not in eid and 'adaptive-k' not in eid:
        if sr < 0.3:
            continue
        method = 'adaptive-conformal-crm-tau025'

    # k2mean
    elif 'k2mean' in eid and 'supp' not in eid:
        if sr < 0.3:
            continue
        method = 'k2mean-baseline'

    # reconvla
    elif 'reconvla' in eid and 'supp' not in eid and sr > 0.3:
        method = 'reconvla'

    else:
        continue

    if method and bench and seed is not None:
        key = (method, bench)
        # Keep highest SR for each seed (handles retries)
        if seed not in results[key] or (results[key][seed] is not None and sr > results[key][seed]):
            results[key][seed] = sr

# ==========================================
# Print the comprehensive table
# ==========================================
print("=" * 100)
print("COMPREHENSIVE RESULTS TABLE: (method, benchmark) -> SR per seed")
print("=" * 100)

methods_order = ['vla-only', 'k2mean-baseline', 'reconvla', 'crm-obs-only-norm005', 'adaptive-conformal-crm-tau025']
benchmarks = ['spatial', 'object', 'goal', 'long']

for method in methods_order:
    print(f"\n{'='*80}")
    print(f"  METHOD: {method}")
    print(f"{'='*80}")
    for bench in benchmarks:
        key = (method, bench)
        if key in results:
            seed_data = results[key]
            seeds_sorted = sorted(seed_data.keys())
            srs = [seed_data[s] for s in seeds_sorted]
            valid_srs = [s for s in srs if s is not None]
            mean_sr = sum(valid_srs) / len(valid_srs) if valid_srs else None
            print(f"\n  [{bench}] ({len(valid_srs)} seeds)")
            for s in seeds_sorted:
                print(f"    seed {s}: SR={seed_data[s]}")
            if mean_sr:
                print(f"    --> MEAN SR = {mean_sr:.4f} ({mean_sr*100:.1f}%)")
        else:
            print(f"\n  [{bench}] NO DATA")

